"""Routewise two-coefficient Wiener gates for residual recurrent blocks.

The controller implements the backward-only operator

    alpha * I + m * J_F

at an internal residual merge.  It deliberately keeps the forward computation
and the block-local parameter gradients unchanged.  The two coefficients are
estimated from periodic quadratic probes, not from cross-example gradient
coherence:

* ``total`` records the two route credits generated by a squared-error probe;
* ``noise`` records the credits generated by Gaussian output noise whose
  covariance is a lagged plug-in estimate from prediction residuals, or by a
  lagged centered residual bootstrap;
* a 2x2, box-constrained Wiener problem produces ``(alpha, m)`` for the next
  training batch.

The residual covariance is a plug-in approximation to conditional observation
noise.  It is intentionally simple and contains no learned sigma head.  The
default statistical assumption is explicit: after the dense warm-up, centered
held-out-like residual variation is treated as diagonal Gaussian noise. A 2-D
field can instead use a stationary per-horizon/channel spatial spectrum. Its
random-phase Gaussian draws retain spatial second-order structure while removing
absolute feature position and phase. A lagged residual bootstrap retains still
more structure without ever forming the full covariance matrix.
A truly cross-fitted covariance file can replace either estimator later
without changing the route solver.
"""

from __future__ import annotations

import os
from collections import deque
from typing import Dict, List, Optional, Tuple

import numpy as np
import torch
import torch.distributed as dist
import torch.nn as nn


def _project_psd_2x2(matrix: torch.Tensor) -> torch.Tensor:
    """Symmetrize 2x2 matrix/matrices and remove negative sampling-noise modes."""

    matrix = 0.5 * (matrix + matrix.transpose(-2, -1))
    values, vectors = torch.linalg.eigh(matrix)
    values = values.clamp_min(0.0)
    return (vectors * values.unsqueeze(-2)) @ vectors.transpose(-2, -1)


def _normalize_rfft2_power(power: torch.Tensor, width: int) -> torch.Tensor:
    """Normalize ``[...,H,W//2+1]`` rFFT power to unit spatial variance."""

    frequency_width = int(width) // 2 + 1
    if power.shape[-1] != frequency_width:
        raise ValueError(
            f"rFFT power width {power.shape[-1]} does not match spatial width {width}"
        )
    weights = power.new_full((frequency_width,), 2.0)
    weights[0] = 1.0
    if int(width) % 2 == 0:
        weights[-1] = 1.0
    variance = (
        power * weights.view(*((1,) * (power.ndim - 1)), -1)
    ).sum(dim=(-2, -1), keepdim=True) / float(power.shape[-2] * int(width))
    return (power / variance.clamp_min(1e-20)).clamp_min(0.0)


def _solve_box_wiener_2x2_batched(
    total: torch.Tensor, noise: torch.Tensor
) -> torch.Tensor:
    """Vectorized exact box solve for arrays shaped ``[..., 2, 2]``.

    U-Net probing can update hundreds of horizon/layer routes at once. Solving
    each 2x2 problem separately launches hundreds of tiny GPU kernels and, in
    the old scalar implementation, also synchronizes the CPU for every route.
    Enumerating the same nine candidates in one batched solve is algebraically
    identical and keeps the whole update on the device.
    """

    if total.shape != noise.shape or total.shape[-2:] != (2, 2):
        raise ValueError("batched Wiener solve expects matching [...,2,2] tensors")
    output_dtype = total.dtype
    output_device = total.device
    total = _project_psd_2x2(total.float())
    noise = _project_psd_2x2(noise.float())
    signal = _project_psd_2x2(total - noise)
    covariance = signal + noise
    scale = covariance.diagonal(dim1=-2, dim2=-1).sum(dim=-1)
    valid = torch.isfinite(scale) & (scale > 1e-20)
    safe_scale = torch.where(valid, scale, torch.ones_like(scale))
    ridge = safe_scale * 1e-6 + 1e-20
    eye = torch.eye(2, device=covariance.device, dtype=covariance.dtype)
    covariance = covariance + ridge[..., None, None] * eye
    ones = torch.ones_like(signal[..., :, 0])
    rhs = torch.matmul(signal, ones.unsqueeze(-1)).squeeze(-1)

    unconstrained = torch.linalg.solve(
        covariance, rhs.unsqueeze(-1)
    ).squeeze(-1)
    candidates: List[torch.Tensor] = [unconstrained]

    # alpha fixed, optimize m on the edge.
    for alpha_value in (0.0, 1.0):
        alpha = torch.full_like(rhs[..., 0], alpha_value)
        branch = (
            (rhs[..., 1] - covariance[..., 0, 1] * alpha)
            / covariance[..., 1, 1]
        ).clamp(0.0, 1.0)
        candidates.append(torch.stack((alpha, branch), dim=-1))
    # m fixed, optimize alpha on the edge.
    for branch_value in (0.0, 1.0):
        branch = torch.full_like(rhs[..., 0], branch_value)
        alpha = (
            (rhs[..., 0] - covariance[..., 0, 1] * branch)
            / covariance[..., 0, 0]
        ).clamp(0.0, 1.0)
        candidates.append(torch.stack((alpha, branch), dim=-1))
    for alpha_value in (0.0, 1.0):
        for branch_value in (0.0, 1.0):
            candidates.append(
                torch.stack(
                    (
                        torch.full_like(rhs[..., 0], alpha_value),
                        torch.full_like(rhs[..., 0], branch_value),
                    ),
                    dim=-1,
                )
            )

    points = torch.stack(candidates, dim=-2)
    objectives = (
        torch.einsum("...bi,...ij,...bj->...b", points, covariance, points)
        - 2.0 * torch.einsum("...bi,...i->...b", points, rhs)
    )
    unconstrained_valid = (
        valid
        & torch.isfinite(unconstrained).all(dim=-1)
        & ((unconstrained >= 0.0) & (unconstrained <= 1.0)).all(dim=-1)
    )
    objectives[..., 0] = torch.where(
        unconstrained_valid,
        objectives[..., 0],
        torch.full_like(objectives[..., 0], float("inf")),
    )
    best = objectives.argmin(dim=-1)
    selected = torch.gather(
        points,
        dim=-2,
        index=best[..., None, None].expand(*best.shape, 1, 2),
    ).squeeze(-2)
    selected = torch.where(valid[..., None], selected, torch.ones_like(selected))
    return selected.to(device=output_device, dtype=output_dtype).clamp(0.0, 1.0)


def solve_box_wiener_2x2(total: torch.Tensor, noise: torch.Tensor) -> torch.Tensor:
    """Solve the constrained two-route Wiener problem exactly in 2D.

    ``total`` estimates ``P + R`` and ``noise`` estimates ``R``.  With
    ``w=(alpha,m)`` and clean target ``s_I+s_J``, the objective (up to a
    constant) is

        w^T (P+R) w - 2 w^T P 1,       0 <= w <= 1.

    Component-wise clipping of the unconstrained solution is not correct when
    the routes are correlated.  We therefore enumerate the unconstrained point,
    the optimum on each of the four edges, and the four corners.
    """

    if total.shape != (2, 2) or noise.shape != (2, 2):
        raise ValueError("solve_box_wiener_2x2 expects two 2x2 matrices")
    return _solve_box_wiener_2x2_batched(
        total.unsqueeze(0), noise.unsqueeze(0)
    )[0]


class _DualWienerRoute(torch.autograd.Function):
    """Identity forward; record an unscaled route VJP and scale its input VJP."""

    @staticmethod
    def forward(ctx, x, controller, which: int, route_index: int, slot: int):
        ctx.controller = controller
        ctx.which = int(which)
        ctx.route_index = int(route_index)
        ctx.slot = int(slot)
        return x

    @staticmethod
    def backward(ctx, grad_out):
        controller = ctx.controller
        controller._record_route(
            ctx.which, ctx.route_index, ctx.slot, grad_out.detach()
        )
        coefficient = controller.route_coefficient(ctx.route_index, ctx.which, grad_out)
        return grad_out * coefficient, None, None, None, None


class _DualWienerBranchState(torch.autograd.Function):
    """Identity forward; gate only credit entering a recurrent branch state.

    The state is an input of the current block, so this scales temporal credit
    to the graph that produced the state while leaving every parameter used by
    the current block on the unscaled side of the gate.  Reading the coefficient
    in ``backward`` also lets calibration VJPs temporarily traverse an all-open
    graph without changing the real forward pass.
    """

    @staticmethod
    def forward(ctx, value, controller, route_index: int):
        ctx.controller = controller
        ctx.route_index = int(route_index)
        return value

    @staticmethod
    def backward(ctx, grad_out):
        coefficient = ctx.controller.route_coefficient(
            ctx.route_index, 1, grad_out
        )
        return grad_out * coefficient, None, None


class DualWienerController(nn.Module):
    """Stateful estimator/router for ``alpha J_skip + m J_branch``.

    An identity residual gives the paper's special case
    ``alpha I + m J_F``; projection skips, such as channel-changing U-Net
    blocks, are handled without changing the estimator.
    """

    def __init__(
        self,
        state_dim: int,
        depth: int,
        *,
        max_horizon: int = 1024,
        ema: float = 0.95,
        residual_ema: float = 0.99,
        warmup_batches: int = 8,
        probe_every: int = 4,
        min_probes: int = 1,
        noise_model: str = "diagonal_gaussian",
        spatial_shape: Optional[Tuple[int, int, int]] = None,
    ) -> None:
        super().__init__()
        self.state_dim = int(state_dim)
        self.depth = int(depth)
        self.max_horizon = int(max_horizon)
        self.ema = float(ema)
        self.residual_ema = float(residual_ema)
        self.warmup_batches = max(1, int(warmup_batches))
        self.probe_every = max(1, int(probe_every))
        self.min_probes = max(1, int(min_probes))
        aliases = {
            "diagonal": "diagonal_gaussian",
            "diag": "diagonal_gaussian",
            "gaussian": "diagonal_gaussian",
            "diagonal_gaussian": "diagonal_gaussian",
            "spectral": "spatial_spectrum",
            "spatial": "spatial_spectrum",
            "spatial_spectrum": "spatial_spectrum",
            "random_phase": "spatial_spectrum",
            "bootstrap": "lagged_residual_bootstrap",
            "structured": "lagged_residual_bootstrap",
            "residual_bootstrap": "lagged_residual_bootstrap",
            "lagged_residual_bootstrap": "lagged_residual_bootstrap",
        }
        requested_noise_model = str(noise_model).strip().lower()
        if requested_noise_model not in aliases:
            raise ValueError(
                "dual Wiener noise_model must be diagonal_gaussian, "
                "spatial_spectrum, or lagged_residual_bootstrap; "
                f"got {noise_model!r}"
            )
        self.noise_model = aliases[requested_noise_model]
        self.spatial_spectrum_oas = str(
            os.environ.get("DUAL_WIENER_SPECTRUM_OAS", "0") or "0"
        ).strip().lower() in ("1", "true", "yes", "on")
        self.spatial_shape: Optional[Tuple[int, int, int]] = None
        if self.noise_model == "spatial_spectrum":
            if spatial_shape is None or len(tuple(spatial_shape)) != 3:
                raise ValueError(
                    "spatial_spectrum noise requires spatial_shape=(channels,height,width)"
                )
            channels, height, width = (int(value) for value in spatial_shape)
            if min(channels, height, width) <= 0:
                raise ValueError(f"invalid dual Wiener spatial_shape={spatial_shape!r}")
            if channels * height * width != self.state_dim:
                raise ValueError(
                    "dual Wiener spatial_shape has "
                    f"D={channels * height * width}, expected state_dim={self.state_dim}"
                )
            self.spatial_shape = (channels, height, width)
        if not 0.0 <= self.ema < 1.0:
            raise ValueError("dual Wiener EMA must lie in [0,1)")
        if not 0.0 <= self.residual_ema < 1.0:
            raise ValueError("dual Wiener residual EMA must lie in [0,1)")

        shape = (self.max_horizon, self.depth)
        self.register_buffer("coefficients", torch.ones(*shape, 2))
        self.register_buffer("total_moments", torch.zeros(*shape, 3))
        self.register_buffer("noise_moments", torch.zeros(*shape, 3))
        self.register_buffer("total_updates", torch.zeros(*shape, dtype=torch.long))
        self.register_buffer("noise_updates", torch.zeros(*shape, dtype=torch.long))
        self.register_buffer("residual_mean", torch.zeros(self.max_horizon, self.state_dim))
        self.register_buffer("residual_second", torch.zeros(self.max_horizon, self.state_dim))
        self.register_buffer("residual_updates", torch.zeros(self.max_horizon, dtype=torch.long))
        self.register_buffer("seen_batches", torch.zeros((), dtype=torch.long))
        self.register_buffer("solved_batches", torch.zeros((), dtype=torch.long))

        # Under stationarity, spatial covariance is diagonal in the Fourier
        # basis. This persistent rFFT power is much smaller than a dense D-by-D
        # covariance and makes an interrupted spectral run exactly resumable.
        spectrum_shape = (
            (
                self.max_horizon,
                self.spatial_shape[0],
                self.spatial_shape[1],
                self.spatial_shape[2] // 2 + 1,
            )
            if self.spatial_shape is not None
            else (0, 0, 0, 0)
        )
        self.register_buffer(
            "spatial_spectrum_power",
            torch.zeros(*spectrum_shape),
            persistent=self.spatial_shape is not None,
        )
        self.register_buffer(
            "spatial_spectrum_updates",
            torch.zeros(
                self.max_horizon if self.spatial_shape is not None else 0,
                dtype=torch.long,
            ),
            persistent=self.spatial_shape is not None,
        )
        # OAS needs the unshrunk running spectrum and its sample count. Keep
        # these ephemeral so old spectral checkpoints remain strict-load
        # compatible; after resume, the saved shrunk spectrum initializes the
        # running estimate on the next batch.
        self.register_buffer(
            "spatial_spectrum_empirical",
            torch.zeros(*spectrum_shape),
            persistent=False,
        )
        self.register_buffer(
            "spatial_spectrum_samples",
            torch.zeros(
                self.max_horizon if self.spatial_shape is not None else 0,
                dtype=torch.long,
            ),
            persistent=False,
        )
        self.register_buffer(
            "spatial_spectrum_oas_shrinkage",
            torch.zeros(
                self.max_horizon if self.spatial_shape is not None else 0
            ),
            persistent=False,
        )

        # One detached residual draw per horizon is a low-memory covariance
        # sketch. Across shuffled batches, outer products of the centered draws
        # retain spatial/channel covariance without storing a D-by-D matrix.
        # Non-persistent buffers keep old checkpoints strict-load compatible.
        template_shape = (
            (self.max_horizon, self.state_dim)
            if self.noise_model == "lagged_residual_bootstrap"
            else (0, 0)
        )
        self.register_buffer(
            "residual_template", torch.zeros(*template_shape), persistent=False
        )
        self.register_buffer(
            "residual_template_valid",
            torch.zeros(
                self.max_horizon
                if self.noise_model == "lagged_residual_bootstrap"
                else 0,
                dtype=torch.bool,
            ),
            persistent=False,
        )

        # Optional validation path: replace the unconditional residual variance
        # with a leakage-free, cross-fitted innovation variance produced by
        # scripts/probe_crossfit_{innovation,scale}.py.  These buffers are
        # deliberately non-persistent: the source file is an explicit part of
        # the run configuration, and old checkpoints must continue to load with
        # strict=True.  The forecasting graph and the 2x2 route solver are
        # unchanged; only the output-space covariance used by the noise probe is
        # replaced.
        self.register_buffer(
            "external_innovation_variance",
            torch.zeros(self.max_horizon, self.state_dim),
            persistent=False,
        )
        self.register_buffer(
            "external_innovation_valid",
            torch.zeros(self.max_horizon, dtype=torch.bool),
            persistent=False,
        )
        # A domain-specific field estimator can supply an absolute innovation
        # spectrum rather than deriving spatial color from the forecasting
        # model's residuals.  The array is kept non-persistent for the same
        # reason as external_innovation_variance: the calibration artifact is
        # an explicit part of the run configuration.  ``rfft2`` is appropriate
        # for doubly-periodic fields (Shear); ``rfft_x`` retains the nonperiodic
        # vertical coordinate and transforms only the periodic x direction
        # (Turbulent Radiative Layer).
        self.register_buffer(
            "external_spatial_innovation_power",
            torch.empty(0, 0, 0, 0),
            persistent=False,
        )
        self._external_spatial_transform = ""
        self._external_spatial_process = False
        self.register_buffer(
            "external_innovation_templates",
            torch.empty(0, 0, 0),
            persistent=False,
        )
        self._external_template_process = False
        # An identifiable linear-Gaussian oracle can additionally provide the
        # one-step AR law.  In that case noise_covector() samples one coherent
        # innovation trajectory across rollout horizons instead of independent
        # marginal draws.  The latter would have the correct variance at every
        # k but the wrong cross-horizon covariance, and therefore would not be
        # an oracle for the summed BPTT gradient.
        self.register_buffer(
            "external_ar_coefficients",
            torch.zeros(self.state_dim),
            persistent=False,
        )
        self.register_buffer(
            "external_ar_innovation_std",
            torch.zeros(self.state_dim),
            persistent=False,
        )
        # General linear-Gaussian process support for covariance-matched
        # estimators.  The older diagonal oracle arrays above remain accepted,
        # but are copied into these matrices so noise_covector() has one joint
        # horizon sampler for both exact and estimated processes.
        self.register_buffer(
            "external_ar_transition_matrix",
            torch.empty(0, 0),
            persistent=False,
        )
        self.register_buffer(
            "external_ar_innovation_factor",
            torch.empty(0, 0),
            persistent=False,
        )
        # A lagged VAR/VARX fit has a latent companion state larger than the
        # observed output.  The observation matrix maps that latent innovation
        # state back to the D-dimensional output covector.  Old D-by-D files
        # simply use the identity and remain byte-for-byte compatible.
        self.register_buffer(
            "external_ar_observation_matrix",
            torch.empty(0, 0),
            persistent=False,
        )
        self.register_buffer(
            "external_ar_valid",
            torch.zeros((), dtype=torch.bool),
            persistent=False,
        )
        self.external_innovation_file = str(
            os.environ.get("DUAL_WIENER_INNOVATION_FILE", "") or ""
        )
        self.external_innovation_key = str(
            os.environ.get("DUAL_WIENER_INNOVATION_KEY", "auto") or "auto"
        )
        self._external_ar_process = False
        self._external_process_estimator = ""
        self._external_needs_noise_reset = False
        if self.external_innovation_file:
            if self.noise_model == "spatial_spectrum":
                self._load_external_spatial_innovation(
                    self.external_innovation_file
                )
            elif self.noise_model == "lagged_residual_bootstrap":
                self._load_external_innovation_templates(
                    self.external_innovation_file
                )
            else:
                self._load_external_innovation_variance(
                    self.external_innovation_file, self.external_innovation_key
                )

        # Ephemeral graph/batch state; none of this belongs in a checkpoint.
        self._collecting = False
        self._mode = "apply"
        self._slot = 0
        self._root_refs: List[torch.Tensor] = []
        self._pair_store: Dict[Tuple[int, int], Tuple[int, torch.Tensor]] = {}
        self._probe_acc: Dict[int, Tuple[torch.Tensor, int]] = {}
        self._probe_total: Optional[torch.Tensor] = None
        self._probe_noise: Optional[torch.Tensor] = None
        self._probe_loss_count = 0
        self._bootstrap_signs: Optional[torch.Tensor] = None
        self._external_ar_noise_state: Optional[torch.Tensor] = None
        self._external_ar_last_horizon = -1
        self._external_template_indices: Optional[torch.Tensor] = None
        self._external_template_signs: Optional[torch.Tensor] = None
        self._external_template_last_horizon = -1
        self._pending_residual: Dict[int, Tuple[torch.Tensor, torch.Tensor, int]] = {}
        self._pending_residual_sample: Dict[int, torch.Tensor] = {}
        self._pending_spatial_power: Dict[int, Tuple[torch.Tensor, int]] = {}
        self._pending_coefficients: Dict[int, torch.Tensor] = {}
        self._last_total_probe = 0.0
        self._last_noise_probe = 0.0
        self._residual_ready_mask = np.zeros(self.max_horizon, dtype=np.bool_)
        self._external_ready_mask = np.zeros(self.max_horizon, dtype=np.bool_)
        self._template_ready_mask = np.zeros(self.max_horizon, dtype=np.bool_)
        self._spectrum_ready_mask = np.zeros(self.max_horizon, dtype=np.bool_)

        # Optional temporal stabilization of the online covariance estimator.
        # OAS regularizes one covariance estimate in output space; it does not
        # protect the sequence of estimates against an unusually low/high probe
        # batch.  These controls act only when explicitly enabled and therefore
        # leave every existing experiment byte-for-byte unchanged.
        self.freeze_gains = str(
            os.environ.get("DUAL_WIENER_FREEZE_GAINS", "0") or "0"
        ).strip().lower() in ("1", "true", "yes", "on")

        def _optional_nonnegative(name: str) -> float:
            raw = str(os.environ.get(name, "") or "").strip()
            if not raw:
                return float("inf")
            value = float(raw)
            if value < 0.0:
                raise ValueError(f"{name} must be nonnegative, got {value}")
            return value

        self.gain_delta_open = _optional_nonnegative(
            "DUAL_WIENER_GAIN_DELTA_OPEN"
        )
        self.gain_delta_close = _optional_nonnegative(
            "DUAL_WIENER_GAIN_DELTA_CLOSE"
        )
        self.noise_guard_window = max(
            0, int(os.environ.get("DUAL_WIENER_NOISE_GUARD_WINDOW", "0") or "0")
        )
        self.noise_guard_min_history = max(
            1,
            int(
                os.environ.get("DUAL_WIENER_NOISE_GUARD_MIN_HISTORY", "3")
                or "3"
            ),
        )
        self.noise_guard_confirmations = max(
            1,
            int(
                os.environ.get("DUAL_WIENER_NOISE_GUARD_CONFIRMATIONS", "2")
                or "2"
            ),
        )
        self.noise_guard_lower = float(
            os.environ.get("DUAL_WIENER_NOISE_GUARD_LOWER", "0.5") or "0.5"
        )
        self.noise_guard_upper = float(
            os.environ.get("DUAL_WIENER_NOISE_GUARD_UPPER", "2.0") or "2.0"
        )
        if not 0.0 < self.noise_guard_lower < 1.0:
            raise ValueError("DUAL_WIENER_NOISE_GUARD_LOWER must lie in (0,1)")
        if self.noise_guard_upper <= 1.0:
            raise ValueError("DUAL_WIENER_NOISE_GUARD_UPPER must be greater than 1")
        initial_scales = []
        for raw in str(
            os.environ.get("DUAL_WIENER_NOISE_GUARD_INITIAL_SCALES", "") or ""
        ).split(","):
            raw = raw.strip()
            if not raw:
                continue
            value = float(raw)
            if np.isfinite(value) and value > 0.0:
                initial_scales.append(value)
        history_size = max(self.noise_guard_window, len(initial_scales), 1)
        self._noise_guard_history = deque(
            initial_scales[-history_size:], maxlen=history_size
        )
        self._noise_guard_pending_direction = 0
        self._noise_guard_pending_values: List[float] = []
        self._gain_updates_rejected = 0
        self._gain_updates_confirmed = 0
        self._last_gain_update_rejected = 0.0
        self._last_gain_update_confirmed = 0.0
        self._last_noise_guard_ratio = 1.0
        self._last_noise_guard_median = 0.0
        self._last_gain_delta_alpha_max = 0.0
        self._last_gain_delta_m_max = 0.0

        # ---- EVALUATION BASELINE ONLY: a frozen constant gain ----------------
        # DUAL_WIENER_CONST=c pins alpha = m = c at every route and disables
        # calibration entirely, giving the static soft-gain control that answers
        # "is the improvement just multiplying the gradient by something small?".
        # It is NOT part of the method: no probe runs, no covariance is
        # estimated, and export_state records const_gain so a run made this way
        # can never be mistaken for a Dual-Wiener run.
        const = os.environ.get("DUAL_WIENER_CONST")
        self.const_gain: Optional[float] = None
        if const not in (None, ""):
            value = float(const)
            if not 0.0 <= value <= 1.0:
                raise ValueError(f"DUAL_WIENER_CONST must lie in [0,1], got {value}")
            self.const_gain = value
            with torch.no_grad():
                self.coefficients.fill_(value)

    def _load_external_spatial_innovation(self, path: str) -> None:
        """Load a training-only absolute field-innovation spectrum.

        Files are produced by ``prepare_thewell_domain_innovation.py``.  Power
        is expressed in the model's normalized output coordinates, so unlike
        the online residual spectrum it carries both covariance geometry and
        absolute noise scale.
        """

        if self.spatial_shape is None:
            raise ValueError("external spatial innovation requires spatial_shape")
        with np.load(path, allow_pickle=False) as archive:
            if "spatial_innovation_power" not in archive.files:
                raise ValueError(
                    "spatial innovation file must contain spatial_innovation_power; "
                    f"available keys={archive.files}"
                )
            power = np.asarray(
                archive["spatial_innovation_power"], dtype=np.float64
            )
            if "spatial_transform" not in archive.files:
                raise ValueError("spatial innovation file lacks spatial_transform")
            transform = str(
                np.asarray(archive["spatial_transform"]).reshape(()).item()
            ).strip().lower()
            estimator = (
                str(
                    np.asarray(archive["innovation_estimator_name"])
                    .reshape(())
                    .item()
                )
                if "innovation_estimator_name" in archive.files
                else "domain_conditional_spatial_wiener"
            )
        channels, height, width = self.spatial_shape
        expected_tail = {
            "rfft2": (channels, height, width // 2 + 1),
            "rfft_x": (channels, height // 2 + 1, width),
        }
        if transform not in expected_tail:
            raise ValueError(
                f"unsupported spatial_transform={transform!r}; use rfft2 or rfft_x"
            )
        if power.ndim != 4 or tuple(power.shape[1:]) != expected_tail[transform]:
            raise ValueError(
                "spatial_innovation_power must have shape [K,%s], got %s"
                % (",".join(str(x) for x in expected_tail[transform]), power.shape)
            )
        if power.shape[0] > self.max_horizon:
            raise ValueError(
                f"spatial innovation K={power.shape[0]} exceeds max_horizon={self.max_horizon}"
            )
        if not np.isfinite(power).all() or np.any(power < 0.0):
            raise ValueError("spatial innovation power must be finite and non-negative")
        loaded = torch.as_tensor(power, dtype=self.external_innovation_variance.dtype)
        self.external_spatial_innovation_power = loaded
        count = int(power.shape[0])
        # The mean spectral power equals mean coordinate variance under an
        # orthonormal FFT.  Store that scalar per horizon in the generic buffer
        # so readiness and exported diagnostics remain shared with vector data.
        mean_variance = loaded.reshape(count, -1).mean(dim=1)
        with torch.no_grad():
            self.external_innovation_variance[:count].copy_(
                mean_variance[:, None].expand(count, self.state_dim)
            )
            self.external_innovation_valid[:count].fill_(True)
        self._external_spatial_transform = transform
        self._external_spatial_process = True
        self._external_process_estimator = estimator
        self._external_needs_noise_reset = True
        print(
            f"[dual-wiener] loaded {estimator.replace('_', ' ')} "
            f"transform={transform} K={count} shape={tuple(power.shape[1:])} "
            f"from {path}",
            flush=True,
        )

    def _load_external_innovation_templates(self, path: str) -> None:
        """Load cross-horizon conditional-innovation trajectories.

        A template is one held-out residual trajectory after applying a
        domain-specific conditional mean.  Resampling one complete trajectory
        per rollout preserves spatial, channel, and cross-horizon covariance;
        this is exactly the structure lost by independent per-horizon Gaussian
        probes.
        """

        with np.load(path, allow_pickle=False) as archive:
            if "innovation_templates" not in archive.files:
                raise ValueError(
                    "external bootstrap file must contain innovation_templates; "
                    f"available keys={archive.files}"
                )
            templates = np.asarray(archive["innovation_templates"], dtype=np.float32)
            estimator = (
                str(
                    np.asarray(archive["innovation_estimator_name"])
                    .reshape(())
                    .item()
                )
                if "innovation_estimator_name" in archive.files
                else "domain_conditional_innovation_bootstrap"
            )
        if templates.ndim < 3:
            raise ValueError(
                "innovation_templates must have shape [N,K,...], got "
                f"{templates.shape}"
            )
        samples, count = int(templates.shape[0]), int(templates.shape[1])
        flat = templates.reshape(samples, count, -1)
        if samples < 2 or count <= 0 or count > self.max_horizon:
            raise ValueError(
                f"invalid innovation template shape {templates.shape} for "
                f"max_horizon={self.max_horizon}"
            )
        if flat.shape[2] != self.state_dim:
            raise ValueError(
                f"innovation templates have D={flat.shape[2]}, expected {self.state_dim}"
            )
        if not np.isfinite(flat).all():
            raise ValueError("innovation templates must be finite")
        # Center each horizon/coordinate across held-out trajectories.  The
        # random sign used at sampling makes the empirical probe zero mean even
        # for a finite template bank, while centering avoids wasting variance
        # on a small calibration-set bias.
        flat = flat - flat.mean(axis=0, keepdims=True)
        loaded = torch.from_numpy(np.ascontiguousarray(flat))
        self.external_innovation_templates = loaded
        variance = loaded.square().mean(dim=0)
        with torch.no_grad():
            self.external_innovation_variance[:count].copy_(variance)
            self.external_innovation_valid[:count].fill_(True)
        self._external_template_process = True
        self._external_process_estimator = estimator
        self._external_needs_noise_reset = True
        print(
            f"[dual-wiener] loaded {estimator.replace('_', ' ')} "
            f"templates N={samples} K={count} D={self.state_dim} from {path}",
            flush=True,
        )

    def _load_external_innovation_variance(self, path: str, key: str) -> None:
        """Load a per-horizon diagonal innovation covariance from ``.npz``.

        The formal scale probe stores fold-specific training-fold estimates as
        ``observed__const_var`` with shape ``[fold,K,D]``.  Averaging those
        already held-out estimates gives the fixed validation covariance used
        here.  The earlier innovation probe stores the OOF innovations directly
        as ``observed__innovation_oof`` with shape ``[N,K,D]``; their variance is
        equivalent.  A direct ``[K,D]`` variance array is also accepted.
        """

        if not os.path.exists(path):
            raise FileNotFoundError(
                f"DUAL_WIENER_INNOVATION_FILE does not exist: {path}"
            )
        oracle_ar_coefficients = None
        oracle_ar_innovation_std = None
        ar_transition_matrix = None
        one_step_innovation_covariance = None
        ar_observation_matrix = None
        estimator_name = ""
        with np.load(path, allow_pickle=False) as archive:
            chosen = key
            if chosen in ("", "auto"):
                for candidate in (
                    "observed__const_var",
                    "observed__innovation_oof",
                    "innovation_variance",
                ):
                    if candidate in archive.files:
                        chosen = candidate
                        break
                else:
                    raise KeyError(
                        "innovation calibration file has none of "
                        "observed__const_var, observed__innovation_oof, or "
                        f"innovation_variance; available keys={archive.files}"
                    )
            if chosen not in archive.files:
                raise KeyError(
                    f"innovation key {chosen!r} is absent from {path}; "
                    f"available keys={archive.files}"
                )
            values = np.asarray(archive[chosen], dtype=np.float64)
            if "oracle_ar_coefficients" in archive.files:
                oracle_ar_coefficients = np.asarray(
                    archive["oracle_ar_coefficients"], dtype=np.float64
                )
                if "oracle_one_step_innovation_std" not in archive.files:
                    raise KeyError(
                        "oracle covariance file contains oracle_ar_coefficients "
                        "but not oracle_one_step_innovation_std"
                    )
                oracle_ar_innovation_std = np.asarray(
                    archive["oracle_one_step_innovation_std"], dtype=np.float64
                )
            matrix_keys = {
                "ar_transition_matrix",
                "one_step_innovation_covariance",
            }
            present_matrix_keys = matrix_keys.intersection(archive.files)
            if present_matrix_keys and present_matrix_keys != matrix_keys:
                missing = sorted(matrix_keys.difference(archive.files))
                raise KeyError(
                    "external linear process file is missing " + ", ".join(missing)
                )
            if present_matrix_keys:
                ar_transition_matrix = np.asarray(
                    archive["ar_transition_matrix"], dtype=np.float64
                )
                one_step_innovation_covariance = np.asarray(
                    archive["one_step_innovation_covariance"], dtype=np.float64
                )
                if "ar_observation_matrix" in archive.files:
                    ar_observation_matrix = np.asarray(
                        archive["ar_observation_matrix"], dtype=np.float64
                    )
            if "innovation_estimator_name" in archive.files:
                estimator_name = str(
                    np.asarray(archive["innovation_estimator_name"]).reshape(()).item()
                )

        if chosen.endswith("__const_var"):
            if values.ndim != 3:
                raise ValueError(
                    f"{chosen} must have shape [fold,K,D], got {values.shape}"
                )
            variance = values.mean(axis=0)
        elif chosen.endswith("__innovation_oof"):
            if values.ndim != 3:
                raise ValueError(
                    f"{chosen} must have shape [N,K,D], got {values.shape}"
                )
            variance = values.var(axis=0)
        else:
            variance = values

        if variance.ndim != 2:
            raise ValueError(
                f"innovation variance must have shape [K,D], got {variance.shape}"
            )
        if int(variance.shape[1]) != self.state_dim:
            raise ValueError(
                f"innovation variance has D={variance.shape[1]}, expected "
                f"state_dim={self.state_dim}"
            )
        if int(variance.shape[0]) > self.max_horizon:
            raise ValueError(
                f"innovation variance has K={variance.shape[0]}, exceeding "
                f"max_horizon={self.max_horizon}"
            )
        if not np.isfinite(variance).all() or np.any(variance < 0.0):
            raise ValueError("innovation variance must be finite and non-negative")

        count = int(variance.shape[0])
        loaded = torch.as_tensor(variance, dtype=self.external_innovation_variance.dtype)
        with torch.no_grad():
            self.external_innovation_variance[:count].copy_(loaded)
            self.external_innovation_valid[:count].fill_(True)
            if oracle_ar_coefficients is not None:
                coefficients = np.asarray(oracle_ar_coefficients).reshape(-1)
                innovation_std = np.asarray(oracle_ar_innovation_std).reshape(-1)
                if coefficients.shape != (self.state_dim,) or innovation_std.shape != (
                    self.state_dim,
                ):
                    raise ValueError(
                        "oracle AR arrays must both have shape "
                        f"[{self.state_dim}], got {coefficients.shape} and "
                        f"{innovation_std.shape}"
                    )
                if (
                    not np.isfinite(coefficients).all()
                    or not np.isfinite(innovation_std).all()
                    or np.any(np.abs(coefficients) >= 1.0)
                    or np.any(innovation_std < 0.0)
                ):
                    raise ValueError("invalid oracle AR coefficients/innovation std")
                expected_std = np.sqrt(np.maximum(1.0 - coefficients**2, 0.0))
                if not np.allclose(innovation_std, expected_std, rtol=2e-5, atol=2e-6):
                    raise ValueError(
                        "oracle_one_step_innovation_std is inconsistent with "
                        "stationary unit-variance AR coefficients"
                    )
                expected_variance = np.stack(
                    [
                        1.0 - np.power(coefficients * coefficients, horizon + 1)
                        for horizon in range(count)
                    ],
                    axis=0,
                )
                if not np.allclose(variance, expected_variance, rtol=2e-5, atol=2e-6):
                    raise ValueError(
                        "innovation_variance is inconsistent with the supplied "
                        "oracle AR process"
                    )
                self.external_ar_coefficients.copy_(
                    torch.as_tensor(coefficients, dtype=self.external_ar_coefficients.dtype)
                )
                self.external_ar_innovation_std.copy_(
                    torch.as_tensor(
                        innovation_std, dtype=self.external_ar_innovation_std.dtype
                    )
                )
                self.external_ar_transition_matrix = torch.diag(
                    torch.as_tensor(
                        coefficients,
                        dtype=self.external_innovation_variance.dtype,
                    )
                )
                self.external_ar_innovation_factor = torch.diag(
                    torch.as_tensor(
                        innovation_std,
                        dtype=self.external_innovation_variance.dtype,
                    )
                )
                self.external_ar_observation_matrix = torch.eye(
                    self.state_dim,
                    dtype=self.external_innovation_variance.dtype,
                )
                self.external_ar_valid.fill_(True)
                self._external_ar_process = True
                self._external_process_estimator = (
                    estimator_name or "oracle_linear_gaussian_process_wiener"
                )
            elif ar_transition_matrix is not None:
                transition = np.asarray(ar_transition_matrix, dtype=np.float64)
                innovation_covariance = np.asarray(
                    one_step_innovation_covariance, dtype=np.float64
                )
                if transition.ndim != 2 or transition.shape[0] != transition.shape[1]:
                    raise ValueError(
                        "external AR transition must be square, got "
                        f"{transition.shape}"
                    )
                latent_dim = int(transition.shape[0])
                if ar_observation_matrix is None:
                    if latent_dim != self.state_dim:
                        raise ValueError(
                            "a latent external AR process must provide "
                            "ar_observation_matrix; got transition shape "
                            f"{transition.shape} for state_dim={self.state_dim}"
                        )
                    observation = np.eye(self.state_dim, dtype=np.float64)
                else:
                    observation = np.asarray(ar_observation_matrix, dtype=np.float64)
                    if observation.shape != (self.state_dim, latent_dim):
                        raise ValueError(
                            "ar_observation_matrix must have shape "
                            f"({self.state_dim},{latent_dim}), got {observation.shape}"
                        )
                if innovation_covariance.shape == (latent_dim, latent_dim):
                    latent_innovation_covariance = innovation_covariance
                elif innovation_covariance.shape == (self.state_dim, self.state_dim):
                    # Companion VAR convention: new output innovation enters
                    # the first D coordinates; lower lag coordinates only shift.
                    latent_innovation_covariance = np.zeros(
                        (latent_dim, latent_dim), dtype=np.float64
                    )
                    latent_innovation_covariance[
                        : self.state_dim, : self.state_dim
                    ] = innovation_covariance
                else:
                    raise ValueError(
                        "one_step_innovation_covariance must have shape "
                        f"({self.state_dim},{self.state_dim}) or "
                        f"({latent_dim},{latent_dim}), got "
                        f"{innovation_covariance.shape}"
                    )
                if not np.isfinite(transition).all() or not np.isfinite(
                    latent_innovation_covariance
                ).all() or not np.isfinite(observation).all():
                    raise ValueError("external linear process arrays must be finite")
                latent_innovation_covariance = 0.5 * (
                    latent_innovation_covariance + latent_innovation_covariance.T
                )
                eigenvalues, eigenvectors = np.linalg.eigh(
                    latent_innovation_covariance
                )
                scale = max(
                    float(np.trace(latent_innovation_covariance)) / latent_dim,
                    1e-12,
                )
                if float(eigenvalues.min()) < -1e-7 * scale:
                    raise ValueError(
                        "one_step_innovation_covariance is not positive semidefinite; "
                        f"minimum eigenvalue={float(eigenvalues.min()):.6g}"
                    )
                eigenvalues = np.maximum(eigenvalues, 0.0)
                positive = eigenvalues > max(scale * 1e-12, 1e-15)
                innovation_factor = (
                    eigenvectors[:, positive]
                    * np.sqrt(eigenvalues[positive]).reshape(1, -1)
                )
                spectral_radius = float(np.max(np.abs(np.linalg.eigvals(transition))))
                if not np.isfinite(spectral_radius) or spectral_radius >= 1.0:
                    raise ValueError(
                        "external AR transition must be stable; spectral radius="
                        f"{spectral_radius:.8g}"
                    )

                # Sum impulse responses instead of propagating a dense latent
                # covariance.  This is exact and much cheaper for companion
                # states because the process-noise rank is at most D.
                impulse = innovation_factor.copy()
                output_covariance = np.zeros(
                    (self.state_dim, self.state_dim), dtype=np.float64
                )
                expected_variance_rows = []
                for _ in range(count):
                    projected = observation @ impulse
                    output_covariance += projected @ projected.T
                    expected_variance_rows.append(np.diag(output_covariance).copy())
                    impulse = transition @ impulse
                expected_variance = np.asarray(expected_variance_rows)
                if not np.allclose(
                    variance, expected_variance, rtol=2e-4, atol=2e-6
                ):
                    raise ValueError(
                        "innovation_variance is inconsistent with the supplied "
                        "linear-Gaussian process"
                    )
                self.external_ar_transition_matrix = torch.as_tensor(
                    transition,
                    dtype=self.external_ar_transition_matrix.dtype,
                )
                self.external_ar_innovation_factor = torch.as_tensor(
                    innovation_factor,
                    dtype=self.external_ar_innovation_factor.dtype,
                )
                self.external_ar_observation_matrix = torch.as_tensor(
                    observation,
                    dtype=self.external_ar_observation_matrix.dtype,
                )
                self.external_ar_valid.fill_(True)
                self._external_ar_process = True
                self._external_process_estimator = (
                    estimator_name or "autocovariance_matched_linear_process_wiener"
                )
        self.external_innovation_key = chosen
        # A resumed checkpoint contains route-noise moments computed from raw
        # residual variance.  Reset them lazily after load_state_dict has run;
        # otherwise EMA=0.95 would retain the very bias this pilot removes.
        reset_old = str(
            os.environ.get("DUAL_WIENER_RESET_NOISE_MOMENTS", "1") or "1"
        ).strip().lower()
        self._external_needs_noise_reset = reset_old not in (
            "0", "false", "no", "off"
        )
        if estimator_name and not self._external_process_estimator:
            self._external_process_estimator = estimator_name
        source_kind = (
            self._external_process_estimator.replace("_", " ")
            if self._external_process_estimator
            else "cross-fitted innovation variance"
        )
        print(
            f"[dual-wiener] loaded {source_kind} key={chosen} "
            f"K={count} D={self.state_dim} from {path}",
            flush=True,
        )

    @property
    def collecting(self) -> bool:
        return bool(self._collecting)

    def _route_index(self, horizon: int, layer: int) -> int:
        horizon = int(horizon)
        layer = int(layer)
        if horizon < 0 or horizon >= self.max_horizon:
            raise ValueError(
                f"dual Wiener horizon {horizon} is outside [0,{self.max_horizon})"
            )
        if layer < 0 or layer >= self.depth:
            raise ValueError(f"dual Wiener layer {layer} is outside [0,{self.depth})")
        return horizon * self.depth + layer

    def begin_batch(self) -> None:
        """Reset ephemeral state and decide whether this batch is a probe batch."""

        self._last_gain_update_rejected = 0.0
        self._last_gain_update_confirmed = 0.0
        self._last_gain_delta_alpha_max = 0.0
        self._last_gain_delta_m_max = 0.0

        # A source checkpoint is loaded after __init__, so its saved route
        # coefficients can overwrite the constructor-time constant fill.  Make
        # the baseline an effective runtime override, not merely an
        # initialization, and keep its checkpoint diagnostics truthful.
        if self.const_gain is not None:
            with torch.no_grad():
                self.coefficients.fill_(self.const_gain)

        if self._external_needs_noise_reset:
            with torch.no_grad():
                self.noise_moments.zero_()
                self.noise_updates.zero_()
            self._external_needs_noise_reset = False
            print(
                "[dual-wiener] cleared checkpoint noise moments before "
                "innovation-calibrated probing",
                flush=True,
            )

        if self.const_gain is not None or self.freeze_gains:
            # The static control has neither probes nor residual statistics,
            # so its batch setup should not synchronize any CUDA scalar.
            self._collecting = False
        else:
            seen = int(self.seen_batches.detach().cpu())
            if self.noise_model == "spatial_spectrum":
                # Spectral moments are accumulated throughout the dense
                # warm-up, not only on the sparse VJP-probe batches.
                self._residual_ready_mask = (
                    self.residual_updates.detach().cpu().numpy() > 0
                )
                self._spectrum_ready_mask = (
                    self.spatial_spectrum_updates.detach().cpu().numpy() > 0
                )
            self._collecting = (
                seen >= self.warmup_batches
                and (seen - self.warmup_batches) % self.probe_every == 0
            )
            if self._collecting:
                # Snapshot the tiny readiness vectors once per probe batch.
                # noise_std() is then called once per horizon; checking a CUDA
                # scalar there caused K separate device synchronizations.
                if self.noise_model != "spatial_spectrum":
                    self._residual_ready_mask = (
                        self.residual_updates.detach().cpu().numpy() > 0
                    )
                self._external_ready_mask = (
                    self.external_innovation_valid.detach().cpu().numpy().astype(np.bool_)
                )
                if self.noise_model == "lagged_residual_bootstrap":
                    self._template_ready_mask = (
                        self.residual_template_valid.detach()
                        .cpu()
                        .numpy()
                        .astype(np.bool_)
                    )
        self._mode = "apply"
        self._slot = 0
        self._root_refs = []
        self._pair_store = {}
        self._probe_acc = {}
        self._probe_total = None
        self._probe_noise = None
        self._probe_loss_count = 0
        self._bootstrap_signs = None
        self._external_ar_noise_state = None
        self._external_ar_last_horizon = -1
        self._external_template_indices = None
        self._external_template_signs = None
        self._external_template_last_horizon = -1
        self._pending_residual = {}
        self._pending_residual_sample = {}
        self._pending_spatial_power = {}
        self._pending_coefficients = {}

    def route_pair(
        self, token: torch.Tensor, horizon: int, layer: int
    ) -> Tuple[torch.Tensor, torch.Tensor]:
        """Return separately gated skip-route and nonlinear references to ``token``."""

        if not torch.is_grad_enabled() or int(horizon) < 0:
            return token, token
        # A windowed autoregressive model can enter the first routed block
        # directly from observed history, so its horizon-zero input has no
        # autograd history.  It is nevertheless a valid probe root: there are
        # no trainable operations upstream to detach, and marking it as a leaf
        # lets autograd.grad traverse every downstream route.  Recurrent models
        # normally arrive here with an already differentiable token.
        if (
            self._collecting
            and int(horizon) == 0
            and int(layer) == 0
            and not token.requires_grad
        ):
            token = token.detach().requires_grad_(True)
        route_index = self._route_index(horizon, layer)
        if not self._collecting:
            # The custom autograd node is needed only while probes record the
            # two route VJPs and temporarily reopen the graph. On ordinary
            # batches, this straight-through expression has exactly the same
            # forward value and input VJP without a Python backward callback
            # at every route.
            pair = self.current_pair(horizon, layer, token)
            detached = token.detach()
            delta = token - detached
            if self.const_gain is not None:
                # With alpha=m=c the two input VJPs can be summed first and
                # scaled once. This is the same c*(J_skip+J_branch)^T VJP and
                # keeps both routes' local parameter gradients fully open.
                shared = detached + pair[0] * delta
                return shared, shared
            return (
                detached + pair[0] * delta,
                detached + pair[1] * delta,
            )
        self._slot += 1
        slot = self._slot
        # One root per independently unrolled start is enough to make
        # autograd.grad traverse every downstream route, without returning K*L
        # large tensors from the probe backward.
        if self._collecting and int(horizon) == 0 and int(layer) == 0:
            self._root_refs.append(token)
        identity = _DualWienerRoute.apply(token, self, 0, route_index, slot)
        nonlinear = _DualWienerRoute.apply(token, self, 1, route_index, slot)
        return identity, nonlinear

    def route_coefficient(
        self, route_index: int, which: int, reference: torch.Tensor
    ) -> torch.Tensor:
        # Both calibration VJPs measure the total/noise route covariance on the
        # fully open graph.  Otherwise a small coefficient would shrink its own
        # next covariance estimate and create a self-closing feedback loop.
        if self._mode in ("total", "noise"):
            return reference.new_tensor(1.0)
        if self.const_gain is not None:
            return reference.new_tensor(self.const_gain)
        horizon, layer = divmod(int(route_index), self.depth)
        return self.coefficients[horizon, layer, int(which)].to(
            device=reference.device, dtype=reference.dtype
        )

    def branch_state_input(
        self, value: torch.Tensor, horizon: int, layer: int
    ) -> torch.Tensor:
        """Scale temporal state input by branch gain while preserving local grads."""

        if not torch.is_grad_enabled() or int(horizon) < 0:
            return value
        route_index = self._route_index(horizon, layer)
        return _DualWienerBranchState.apply(value, self, route_index)

    def current_pair(self, horizon: int, layer: int, reference: torch.Tensor) -> torch.Tensor:
        horizon = int(horizon)
        if self.const_gain is not None:
            return reference.new_full((2,), self.const_gain)
        # Evaluation may free-roll far beyond the training/calibration horizon
        # (e.g. Mackey-Glass has >1024 test steps).  Under no_grad the router is
        # value-identical and applies no coefficient, so an out-of-table pair is
        # diagnostics only. Report fully open instead of indexing past the
        # allocated statistics. During training, route_pair() remains strict and
        # raises before this point if max_horizon is genuinely too small for K.
        if horizon < 0 or horizon >= self.max_horizon:
            return reference.new_ones(2)
        route_index = self._route_index(horizon, layer)
        h, l = divmod(route_index, self.depth)
        return self.coefficients[h, l].to(device=reference.device, dtype=reference.dtype)

    def observe_residual(self, horizon: int, residual: torch.Tensor) -> None:
        """Accumulate residual moments; commit only after the batch finishes."""

        horizon = int(horizon)
        if horizon < 0 or horizon >= self.max_horizon:
            return
        flat = residual.detach().reshape(residual.shape[0], -1).float()
        if flat.shape[1] != self.state_dim:
            raise ValueError(
                f"dual Wiener residual has D={flat.shape[1]}, expected {self.state_dim}"
            )
        if (
            self.noise_model == "spatial_spectrum"
            and bool(self._residual_ready_mask[horizon])
        ):
            assert self.spatial_shape is not None
            field = flat.reshape(flat.shape[0], *self.spatial_shape)
            mean = self.residual_mean[horizon].reshape(self.spatial_shape)
            second = self.residual_second[horizon].reshape(self.spatial_shape)
            variance = (second - mean.square()).clamp_min(0.0)
            floor = second.mean().clamp_min(1e-20) * 1e-8
            standardized = (field - mean.unsqueeze(0)) / torch.sqrt(
                variance + floor
            ).unsqueeze(0)
            transform = torch.fft.rfft2(
                standardized, dim=(-2, -1), norm="ortho"
            )
            power_sum = transform.abs().square().sum(dim=0).detach()
            previous_power = self._pending_spatial_power.get(horizon)
            if previous_power is None:
                self._pending_spatial_power[horizon] = (
                    power_sum,
                    int(field.shape[0]),
                )
            else:
                self._pending_spatial_power[horizon] = (
                    previous_power[0] + power_sum,
                    previous_power[1] + int(field.shape[0]),
                )
        sums = flat.sum(dim=0)
        seconds = (flat * flat).sum(dim=0)
        count = int(flat.shape[0])
        if (
            self.noise_model == "lagged_residual_bootstrap"
            and horizon not in self._pending_residual_sample
        ):
            # The data loader and random rollout start make the first item a
            # stochastic draw. Keep it detached and commit it only after this
            # batch, so the next probe is leakage-free with respect to the
            # current prediction graph.
            self._pending_residual_sample[horizon] = flat[0].clone()
        previous = self._pending_residual.get(horizon)
        if previous is None:
            self._pending_residual[horizon] = (sums, seconds, count)
        else:
            self._pending_residual[horizon] = (
                previous[0] + sums,
                previous[1] + seconds,
                previous[2] + count,
            )

    def noise_std(self, horizon: int, reference: torch.Tensor) -> Optional[torch.Tensor]:
        horizon = int(horizon)
        if horizon < 0 or horizon >= self.max_horizon:
            return None
        if bool(self._external_ready_mask[horizon]):
            variance = self.external_innovation_variance[horizon].clamp_min(0.0)
            second_scale = variance.mean()
        else:
            if not bool(self._residual_ready_mask[horizon]):
                return None
            mean = self.residual_mean[horizon]
            second = self.residual_second[horizon]
            variance = (second - mean * mean).clamp_min(0.0)
            second_scale = second.mean()
        # Numerical floor only; it scales with the estimated second moment and
        # is not a tunable noise prior.
        floor = second_scale.clamp_min(1e-20) * 1e-8
        sigma = torch.sqrt(variance + floor)
        sigma = sigma.to(device=reference.device, dtype=reference.dtype)
        sigma = sigma.reshape(1, *reference.shape[1:])
        return sigma.expand_as(reference)

    def noise_covector(
        self, horizon: int, reference: torch.Tensor
    ) -> Optional[torch.Tensor]:
        """Draw a detached zero-mean output covector for the noise VJP.

        ``diagonal_gaussian`` realizes ``diag(var(residual))``. The spectral
        alternative colors white Gaussian fields by a lagged random-phase 2-D
        residual spectrum. The bootstrap uses a lagged centered residual draw.
        If ``B`` denotes the linear map from output covectors to a route VJP,
        averaging their outer products estimates ``B R B^T`` without
        materializing the output covariance ``R`` itself.
        """

        horizon = int(horizon)
        if horizon < 0 or horizon >= self.max_horizon:
            return None
        if self._external_template_process:
            if not bool(self._external_ready_mask[horizon]):
                return None
            flat_reference = reference.reshape(reference.shape[0], -1)
            if flat_reference.shape[1] != self.state_dim:
                raise ValueError(
                    "external innovation-template reference has D="
                    f"{flat_reference.shape[1]}, expected {self.state_dim}"
                )
            if horizon == 0:
                sample_count = int(self.external_innovation_templates.shape[0])
                self._external_template_indices = torch.randint(
                    sample_count,
                    (flat_reference.shape[0],),
                    device=reference.device,
                )
                self._external_template_signs = torch.empty(
                    flat_reference.shape[0], 1,
                    device=reference.device,
                    dtype=reference.dtype,
                ).bernoulli_(0.5).mul_(2.0).sub_(1.0)
            elif (
                self._external_template_indices is None
                or self._external_template_signs is None
                or self._external_template_last_horizon != horizon - 1
                or self._external_template_indices.shape[0] != flat_reference.shape[0]
            ):
                raise RuntimeError(
                    "external innovation templates must be sampled in contiguous "
                    f"horizon order starting at zero; got horizon={horizon} "
                    f"after {self._external_template_last_horizon}"
                )
            assert self._external_template_indices is not None
            assert self._external_template_signs is not None
            bank = self.external_innovation_templates[:, horizon].to(
                device=reference.device, dtype=reference.dtype
            )
            draw = bank.index_select(0, self._external_template_indices)
            self._external_template_last_horizon = horizon
            return (draw * self._external_template_signs).reshape_as(reference).detach()
        if self._external_spatial_process:
            if not bool(self._external_ready_mask[horizon]):
                return None
            assert self.spatial_shape is not None
            if tuple(reference.shape[-3:]) != self.spatial_shape:
                raise ValueError(
                    "external spatial reference has trailing shape "
                    f"{tuple(reference.shape[-3:])}, expected {self.spatial_shape}"
                )
            power = self.external_spatial_innovation_power[horizon].to(
                device=reference.device, dtype=torch.float32
            ).clamp_min(0.0)
            white = torch.randn(
                reference.shape, device=reference.device, dtype=torch.float32
            )
            if self._external_spatial_transform == "rfft2":
                white_spectrum = torch.fft.rfft2(
                    white, dim=(-2, -1), norm="ortho"
                )
                colored = torch.fft.irfft2(
                    white_spectrum * power.sqrt().reshape(
                        *((1,) * (reference.ndim - 3)), *power.shape
                    ),
                    s=self.spatial_shape[-2:],
                    dim=(-2, -1),
                    norm="ortho",
                )
            elif self._external_spatial_transform == "rfft_x":
                # The Well stores fields as [x,y].  Turbulent Radiative Layer
                # is periodic in x and open in y, hence the transform is -2.
                white_spectrum = torch.fft.rfft(white, dim=-2, norm="ortho")
                colored = torch.fft.irfft(
                    white_spectrum * power.sqrt().reshape(
                        *((1,) * (reference.ndim - 3)), *power.shape
                    ),
                    n=self.spatial_shape[-2],
                    dim=-2,
                    norm="ortho",
                )
            else:  # guarded at file load; keep a local invariant check.
                raise RuntimeError(
                    "invalid external spatial transform "
                    f"{self._external_spatial_transform!r}"
                )
            return colored.to(dtype=reference.dtype).detach()
        if self._external_ar_process:
            if not bool(self._external_ready_mask[horizon]):
                return None
            flat_reference = reference.reshape(reference.shape[0], -1)
            if flat_reference.shape[1] != self.state_dim:
                raise ValueError(
                    "oracle AR noise reference has D="
                    f"{flat_reference.shape[1]}, expected {self.state_dim}"
                )
            # Calls are horizon-ordered inside each rollout start. Horizon zero
            # marks a new independent future-noise trajectory. Refuse to hide a
            # call-order bug by silently replacing a joint draw with independent
            # per-horizon marginals.
            transition = self.external_ar_transition_matrix.to(
                device=reference.device, dtype=reference.dtype
            )
            innovation_factor = self.external_ar_innovation_factor.to(
                device=reference.device, dtype=reference.dtype
            )
            observation = self.external_ar_observation_matrix.to(
                device=reference.device, dtype=reference.dtype
            )
            latent_dim = int(transition.shape[0])
            if horizon == 0:
                previous = torch.zeros(
                    flat_reference.shape[0],
                    latent_dim,
                    device=reference.device,
                    dtype=reference.dtype,
                )
            else:
                if (
                    self._external_ar_noise_state is None
                    or self._external_ar_last_horizon != horizon - 1
                    or self._external_ar_noise_state.shape
                    != (flat_reference.shape[0], latent_dim)
                ):
                    raise RuntimeError(
                        "oracle AR innovation probes must be called in contiguous "
                        f"horizon order starting at zero; got horizon={horizon} "
                        f"after {self._external_ar_last_horizon}"
                    )
                previous = self._external_ar_noise_state
            white = torch.randn(
                flat_reference.shape[0],
                innovation_factor.shape[1],
                device=reference.device,
                dtype=reference.dtype,
            )
            current = (
                previous @ transition.transpose(0, 1)
                + white @ innovation_factor.transpose(0, 1)
            ).detach()
            self._external_ar_noise_state = current
            self._external_ar_last_horizon = horizon
            observed = current @ observation.transpose(0, 1)
            return observed.reshape_as(reference)
        if self.noise_model == "spatial_spectrum":
            if not bool(self._spectrum_ready_mask[horizon]):
                return None
            assert self.spatial_shape is not None
            if tuple(reference.shape[-3:]) != self.spatial_shape:
                raise ValueError(
                    "spatial-spectrum reference has trailing shape "
                    f"{tuple(reference.shape[-3:])}, expected {self.spatial_shape}"
                )
            sigma = self.noise_std(horizon, reference)
            if sigma is None:
                return None
            # FFT in float32 even under autocast: CUDA half/bfloat FFTs impose
            # power-of-two restrictions that ordinary field grids need not meet.
            white = torch.randn(
                reference.shape, device=reference.device, dtype=torch.float32
            )
            white_spectrum = torch.fft.rfft2(
                white, dim=(-2, -1), norm="ortho"
            )
            color = self.spatial_spectrum_power[horizon].clamp_min(0.0).sqrt()
            color = color.reshape(
                *((1,) * (reference.ndim - 3)), *color.shape
            )
            standardized = torch.fft.irfft2(
                white_spectrum * color,
                s=self.spatial_shape[-2:],
                dim=(-2, -1),
                norm="ortho",
            )
            return (
                standardized.to(dtype=reference.dtype) * sigma
            ).detach()
        if self.noise_model == "lagged_residual_bootstrap":
            if not bool(self._template_ready_mask[horizon]):
                return None
            centered = self.residual_template[horizon] - self.residual_mean[horizon]
            centered = centered.to(device=reference.device, dtype=reference.dtype)
            centered = centered.reshape(1, *reference.shape[1:]).expand_as(reference)
            # A Rademacher sign makes the probe explicitly zero mean. Reuse the
            # same sign tensor at every horizon in this probe rollout so the
            # lagged sample retains cross-horizon as well as spatial covariance.
            sign_shape = (reference.shape[0],) + (1,) * (reference.ndim - 1)
            if (
                self._bootstrap_signs is None
                or tuple(self._bootstrap_signs.shape) != sign_shape
                or self._bootstrap_signs.device != reference.device
                or self._bootstrap_signs.dtype != reference.dtype
            ):
                self._bootstrap_signs = torch.empty(
                    sign_shape, device=reference.device, dtype=reference.dtype
                ).bernoulli_(0.5).mul_(2.0).sub_(1.0)
            return (centered * self._bootstrap_signs).detach()

        sigma = self.noise_std(horizon, reference)
        if sigma is None:
            return None
        return (sigma * torch.randn_like(reference)).detach()

    def probe_terms(
        self, prediction: torch.Tensor, target: torch.Tensor, horizon: int
    ) -> Tuple[Optional[torch.Tensor], Optional[torch.Tensor]]:
        """Build matched quadratic total/noise probe terms for one prediction."""

        # A frozen constant-gain baseline never consumes residual moments.
        # Skipping them avoids K large reductions and K state updates per
        # micro-batch while leaving the baseline's gradients unchanged.
        if self.const_gain is not None:
            return None, None
        self.observe_residual(horizon, prediction - target)
        if not self._collecting:
            return None, None
        noise_covector = self.noise_covector(horizon, prediction)
        if noise_covector is None:
            return None, None
        residual = prediction - target
        total = 0.5 * (residual * residual).mean()
        noise = (prediction * noise_covector).mean()
        return total, noise

    def set_probe_losses(
        self, total: Optional[torch.Tensor], noise: Optional[torch.Tensor]
    ) -> None:
        """Accumulate matched probe objectives from independent rollouts.

        Recurrent-state training builds all sampled rollout starts in one
        function call, whereas generic windowed-history training calls the
        rollout loss once per start.  Accumulating here gives both paths the
        same batch-level mean without making the trainer architecture-aware.
        """

        if total is None or noise is None:
            return
        self._probe_total = total if self._probe_total is None else self._probe_total + total
        self._probe_noise = noise if self._probe_noise is None else self._probe_noise + noise
        self._probe_loss_count += 1

    def _record_route(
        self, which: int, route_index: int, slot: int, gradient: torch.Tensor
    ) -> None:
        if self._mode not in ("total", "noise"):
            return
        key = (int(slot), int(route_index))
        held = self._pair_store.pop(key, None)
        flattened = gradient.reshape(gradient.shape[0], -1).float()
        if held is None:
            self._pair_store[key] = (int(which), flattened)
            return
        if held[0] == int(which) or held[1].shape != flattened.shape:
            return
        identity = held[1] if held[0] == 0 else flattened
        branch = flattened if held[0] == 0 else held[1]
        moment = torch.stack(
            (
                (identity * identity).mean(),
                (identity * branch).mean(),
                (branch * branch).mean(),
            )
        ).detach()
        previous = self._probe_acc.get(int(route_index))
        if previous is None:
            self._probe_acc[int(route_index)] = (moment, 1)
        else:
            self._probe_acc[int(route_index)] = (previous[0] + moment, previous[1] + 1)

    def _update_probe_moments(self, mode: str) -> List[int]:
        target = self.total_moments if mode == "total" else self.noise_moments
        counts = self.total_updates if mode == "total" else self.noise_updates
        flat_target = target.view(-1, 3)
        distributed = bool(
            dist.is_available()
            and dist.is_initialized()
            and dist.get_world_size() > 1
        )
        if distributed:
            # Every DDP rank sees a different data shard and a different noise
            # draw.  Pool the raw route-moment sums before the running mean/EMA
            # update so all ranks solve one global Wiener problem.  Averaging
            # already-solved gains would be incorrect because the box solve is
            # nonlinear.  This collective is tiny: H x depth x (3 moments + 1
            # count), independent of the state dimension.
            moment_sums = torch.zeros_like(flat_target)
            observation_counts = torch.zeros(
                flat_target.shape[0],
                device=target.device,
                dtype=torch.long,
            )
            for route_index, (moment_sum, observation_count) in self._probe_acc.items():
                moment_sums[int(route_index)].copy_(moment_sum)
                observation_counts[int(route_index)] = int(observation_count)
            dist.all_reduce(moment_sums, op=dist.ReduceOp.SUM)
            dist.all_reduce(observation_counts, op=dist.ReduceOp.SUM)
            updated_tensor = torch.nonzero(
                observation_counts > 0, as_tuple=False
            ).flatten()
            updated = updated_tensor.tolist()
            values = (
                moment_sums.index_select(0, updated_tensor)
                / observation_counts.index_select(0, updated_tensor)
                .clamp_min(1)
                .to(moment_sums.dtype)[:, None]
            )
        else:
            updated = sorted(self._probe_acc)
            values = (
                torch.stack(
                    [
                        self._probe_acc[index][0]
                        / max(self._probe_acc[index][1], 1)
                        for index in updated
                    ]
                )
                if updated
                else flat_target.new_empty((0, 3))
            )
        if updated:
            route_indices = torch.as_tensor(
                updated, device=target.device, dtype=torch.long
            )
            flat_counts = counts.view(-1)
            previous = flat_target.index_select(0, route_indices)
            previous_counts = flat_counts.index_select(0, route_indices)
            initialized = previous_counts > 0
            # The old controller applied its first gain after one route probe.
            # That first sample is precisely where the covariance difference
            # T-R is least stable.  During a pooled initialization, use the
            # exact arithmetic mean for the first ``min_probes`` observations
            # and keep the route fully open until both T and R reach that
            # count.  Once initialized, retain the original EMA so the moments
            # can track the slowly changing model rather than freezing a pilot.
            running_values = (
                previous * previous_counts[:, None].to(previous.dtype) + values
            ) / (previous_counts[:, None].to(previous.dtype) + 1.0)
            ema_values = previous * self.ema + values * (1.0 - self.ema)
            bootstrap = previous_counts < self.min_probes
            initialized_values = torch.where(
                bootstrap[:, None], running_values, ema_values
            )
            next_values = torch.where(
                initialized[:, None], initialized_values, values
            )
            flat_target.index_copy_(0, route_indices, next_values)
            flat_counts.index_add_(
                0, route_indices, torch.ones_like(route_indices)
            )
        self._probe_acc = {}
        self._pair_store = {}
        return updated

    def _run_probe(self, loss: torch.Tensor, mode: str) -> List[int]:
        self._mode = mode
        self._probe_acc = {}
        self._pair_store = {}
        refs = [ref for ref in self._root_refs if ref.requires_grad]
        if not refs:
            return []
        torch.autograd.grad(
            loss,
            refs,
            retain_graph=True,
            create_graph=False,
            allow_unused=True,
        )
        return self._update_probe_moments(mode)

    def _accept_noise_probe_scale(self, scale: float) -> bool:
        """Return whether an online noise-scale observation may update gains.

        The history contains accepted observations only.  One outlier is held
        back; a second independent outlier in the same direction confirms a
        distribution shift and both observations enter the running median.
        This protects against isolated low-energy probes without permanently
        rejecting a real change in the process scale.
        """

        if self.noise_guard_window <= 0:
            return True
        history = list(self._noise_guard_history)[-self.noise_guard_window :]
        if len(history) < self.noise_guard_min_history:
            self._noise_guard_history.append(float(scale))
            self._noise_guard_pending_direction = 0
            self._noise_guard_pending_values = []
            return True
        median = float(np.median(np.asarray(history, dtype=np.float64)))
        ratio = float(scale / max(median, 1e-30))
        self._last_noise_guard_median = median
        self._last_noise_guard_ratio = ratio
        direction = -1 if ratio < self.noise_guard_lower else (
            1 if ratio > self.noise_guard_upper else 0
        )
        if direction == 0:
            self._noise_guard_history.append(float(scale))
            self._noise_guard_pending_direction = 0
            self._noise_guard_pending_values = []
            return True
        if direction != self._noise_guard_pending_direction:
            self._noise_guard_pending_direction = direction
            self._noise_guard_pending_values = [float(scale)]
        else:
            self._noise_guard_pending_values.append(float(scale))
        if len(self._noise_guard_pending_values) < self.noise_guard_confirmations:
            self._gain_updates_rejected += 1
            self._last_gain_update_rejected = 1.0
            return False

        # A repeated excursion is evidence for a scale shift rather than one
        # unlucky probe.  Admit the confirming observations together so the
        # median can track the new regime instead of rejecting it forever.
        for value in self._noise_guard_pending_values:
            self._noise_guard_history.append(value)
        self._noise_guard_pending_direction = 0
        self._noise_guard_pending_values = []
        self._gain_updates_confirmed += 1
        self._last_gain_update_confirmed = 1.0
        return True

    def calibrate(self) -> bool:
        """Measure route covariances and stage gains for the next batch."""

        if (
            not self._collecting
            or self._probe_total is None
            or self._probe_noise is None
            or not self._root_refs
        ):
            self._mode = "apply"
            return False
        count = max(int(self._probe_loss_count), 1)
        total_probe = self._probe_total / count
        noise_probe = self._probe_noise / count
        self._last_total_probe = float(total_probe.detach().cpu())
        noise_scale = noise_probe.detach().abs().float()
        if (
            dist.is_available()
            and dist.is_initialized()
            and dist.get_world_size() > 1
        ):
            # Every rank must make exactly the same guard decision; otherwise
            # the controller buffers diverge even though DDP parameters do not.
            dist.all_reduce(noise_scale, op=dist.ReduceOp.SUM)
            noise_scale.div_(dist.get_world_size())
        self._last_noise_probe = float(noise_scale.cpu())
        if not self._accept_noise_probe_scale(self._last_noise_probe):
            self._mode = "apply"
            return False
        total_keys = set(self._run_probe(total_probe, "total"))
        noise_keys = set(self._run_probe(noise_probe, "noise"))
        route_indices = sorted(total_keys & noise_keys)
        if route_indices and self.min_probes > 1:
            candidate_indices = torch.as_tensor(
                route_indices, device=self.total_updates.device, dtype=torch.long
            )
            total_counts = self.total_updates.view(-1).index_select(
                0, candidate_indices
            )
            noise_counts = self.noise_updates.view(-1).index_select(
                0, candidate_indices
            )
            ready = (total_counts >= self.min_probes) & (
                noise_counts >= self.min_probes
            )
            route_indices = [
                route for route, is_ready in zip(route_indices, ready.tolist())
                if is_ready
            ]
        if route_indices:
            flat_indices = torch.as_tensor(
                route_indices, device=self.total_moments.device, dtype=torch.long
            )
            total_vec = self.total_moments.view(-1, 3).index_select(0, flat_indices)
            noise_vec = self.noise_moments.view(-1, 3).index_select(0, flat_indices)
            total_matrix = torch.stack(
                (
                    torch.stack((total_vec[:, 0], total_vec[:, 1]), dim=-1),
                    torch.stack((total_vec[:, 1], total_vec[:, 2]), dim=-1),
                ),
                dim=-2,
            )
            noise_matrix = torch.stack(
                (
                    torch.stack((noise_vec[:, 0], noise_vec[:, 1]), dim=-1),
                    torch.stack((noise_vec[:, 1], noise_vec[:, 2]), dim=-1),
                ),
                dim=-2,
            )
            gains = _solve_box_wiener_2x2_batched(
                total_matrix, noise_matrix
            ).detach()
            self._pending_coefficients.update(
                dict(zip(route_indices, gains.unbind(0)))
            )
        self._mode = "apply"
        return bool(self._pending_coefficients)

    def _flush_residuals(self) -> None:
        horizons = sorted(self._pending_residual)
        if not horizons:
            return
        indices = torch.as_tensor(
            horizons, device=self.residual_mean.device, dtype=torch.long
        )
        means = torch.stack(
            [
                self._pending_residual[h][0]
                / max(self._pending_residual[h][2], 1)
                for h in horizons
            ]
        )
        seconds = torch.stack(
            [
                self._pending_residual[h][1]
                / max(self._pending_residual[h][2], 1)
                for h in horizons
            ]
        )
        old_means = self.residual_mean.index_select(0, indices)
        old_seconds = self.residual_second.index_select(0, indices)
        initialized = self.residual_updates.index_select(0, indices) > 0
        next_means = torch.where(
            initialized[:, None],
            old_means * self.residual_ema + means * (1.0 - self.residual_ema),
            means,
        )
        next_seconds = torch.where(
            initialized[:, None],
            old_seconds * self.residual_ema + seconds * (1.0 - self.residual_ema),
            seconds,
        )
        self.residual_mean.index_copy_(0, indices, next_means)
        self.residual_second.index_copy_(0, indices, next_seconds)
        self.residual_updates.index_add_(0, indices, torch.ones_like(indices))
        if self.noise_model == "spatial_spectrum":
            spectral_horizons = sorted(self._pending_spatial_power)
            if spectral_horizons:
                assert self.spatial_shape is not None
                spectral_indices = torch.as_tensor(
                    spectral_horizons,
                    device=self.spatial_spectrum_power.device,
                    dtype=torch.long,
                )
                spectral_values = torch.stack(
                    [
                        self._pending_spatial_power[horizon][0]
                        / max(self._pending_spatial_power[horizon][1], 1)
                        for horizon in spectral_horizons
                    ]
                )
                spectral_values = _normalize_rfft2_power(
                    spectral_values, self.spatial_shape[-1]
                )
                old_power = self.spatial_spectrum_power.index_select(
                    0, spectral_indices
                )
                initialized_power = self.spatial_spectrum_updates.index_select(
                    0, spectral_indices
                ) > 0
                if self.spatial_spectrum_oas:
                    old_empirical = self.spatial_spectrum_empirical.index_select(
                        0, spectral_indices
                    )
                    old_samples = self.spatial_spectrum_samples.index_select(
                        0, spectral_indices
                    )
                    # Non-persistent OAS accumulators are empty after resume;
                    # seed them from the persistent spectrum rather than
                    # discarding all pre-resume information.
                    resume_only = (old_samples == 0) & initialized_power
                    old_empirical = torch.where(
                        resume_only[:, None, None, None], old_power, old_empirical
                    )
                    old_samples = torch.where(
                        resume_only, torch.ones_like(old_samples), old_samples
                    )
                    new_samples = torch.as_tensor(
                        [
                            self._pending_spatial_power[horizon][1]
                            for horizon in spectral_horizons
                        ],
                        device=old_samples.device,
                        dtype=old_samples.dtype,
                    )
                    total_samples = old_samples + new_samples
                    empirical = (
                        old_empirical * old_samples[:, None, None, None]
                        + spectral_values * new_samples[:, None, None, None]
                    ) / total_samples.clamp_min(1)[:, None, None, None]
                    empirical = _normalize_rfft2_power(
                        empirical, self.spatial_shape[-1]
                    )
                    # Fourier stationarity diagonalizes the covariance. OAS
                    # shrinks its empirical eigenvalues toward the white
                    # spectrum (unit power after normalization), separately
                    # for every horizon and channel.
                    dimension = float(
                        self.spatial_shape[-2] * self.spatial_shape[-1]
                    )
                    # ``empirical`` stores only the non-redundant rFFT half
                    # plane.  OAS depends on tr(S) and tr(S^2), so interior
                    # horizontal frequencies must count twice to represent
                    # their omitted conjugates.  After normalization tr(S)=p,
                    # but retaining the explicit expression is both cheap and
                    # robust to roundoff.
                    frequency_width = empirical.shape[-1]
                    fft_weights = empirical.new_full((frequency_width,), 2.0)
                    fft_weights[0] = 1.0
                    if self.spatial_shape[-1] % 2 == 0:
                        fft_weights[-1] = 1.0
                    fft_weights = fft_weights.view(1, 1, 1, frequency_width)
                    trace = (empirical * fft_weights).sum(dim=(-2, -1))
                    trace_square = (
                        empirical.square() * fft_weights
                    ).sum(dim=(-2, -1))
                    reciprocal_dimension = 1.0 / dimension
                    numerator = (
                        (1.0 - 2.0 * reciprocal_dimension) * trace_square
                        + trace.square()
                    )
                    denominator = (
                        total_samples.float()[:, None]
                        + 1.0
                        - 2.0 * reciprocal_dimension
                    ) * (
                        trace_square - trace.square() * reciprocal_dimension
                    )
                    shrinkage = torch.where(
                        denominator > 0.0,
                        (numerator / denominator).clamp(0.0, 1.0),
                        torch.ones_like(trace),
                    )
                    next_power = (
                        (1.0 - shrinkage[..., None, None]) * empirical
                        + shrinkage[..., None, None]
                    )
                    next_power = _normalize_rfft2_power(
                        next_power, self.spatial_shape[-1]
                    )
                    self.spatial_spectrum_empirical.index_copy_(
                        0, spectral_indices, empirical
                    )
                    self.spatial_spectrum_samples.index_copy_(
                        0, spectral_indices, total_samples
                    )
                    self.spatial_spectrum_oas_shrinkage.index_copy_(
                        0, spectral_indices, shrinkage.mean(dim=1)
                    )
                else:
                    ema_power = (
                        old_power * self.residual_ema
                        + spectral_values * (1.0 - self.residual_ema)
                    )
                    next_power = torch.where(
                        initialized_power[:, None, None, None],
                        ema_power,
                        spectral_values,
                    )
                # Convex combinations of normalized spectra remain normalized.
                self.spatial_spectrum_power.index_copy_(
                    0, spectral_indices, next_power
                )
                self.spatial_spectrum_updates.index_add_(
                    0, spectral_indices, torch.ones_like(spectral_indices)
                )
        if self.noise_model == "lagged_residual_bootstrap":
            sampled_horizons = [
                horizon
                for horizon in horizons
                if horizon in self._pending_residual_sample
            ]
            if sampled_horizons:
                sample_indices = torch.as_tensor(
                    sampled_horizons,
                    device=self.residual_template.device,
                    dtype=torch.long,
                )
                samples = torch.stack(
                    [self._pending_residual_sample[h] for h in sampled_horizons]
                ).to(device=self.residual_template.device)
                self.residual_template.index_copy_(0, sample_indices, samples)
                self.residual_template_valid.index_fill_(0, sample_indices, True)

    def end_batch(self) -> None:
        """Commit lagged gains and residual covariance after the real backward."""

        if self._pending_coefficients:
            route_indices = sorted(self._pending_coefficients)
            indices = torch.as_tensor(
                route_indices, device=self.coefficients.device, dtype=torch.long
            )
            candidates = torch.stack(
                [self._pending_coefficients[index] for index in route_indices]
            )
            previous = self.coefficients.view(-1, 2).index_select(0, indices)
            delta = candidates - previous
            if np.isfinite(self.gain_delta_close):
                delta = delta.clamp_min(-float(self.gain_delta_close))
            if np.isfinite(self.gain_delta_open):
                delta = delta.clamp_max(float(self.gain_delta_open))
            values = (previous + delta).clamp_(0.0, 1.0)
            applied = values - previous
            self._last_gain_delta_alpha_max = float(
                applied[:, 0].abs().max().detach().cpu()
            )
            self._last_gain_delta_m_max = float(
                applied[:, 1].abs().max().detach().cpu()
            )
            self.coefficients.view(-1, 2).index_copy_(0, indices, values)
            self.solved_batches.add_(1)
        self._flush_residuals()
        self.seen_batches.add_(1)
        self._collecting = False
        self._mode = "apply"
        self._root_refs = []
        self._pair_store = {}
        self._probe_acc = {}
        self._probe_total = None
        self._probe_noise = None
        self._probe_loss_count = 0
        self._bootstrap_signs = None
        self._pending_residual = {}
        self._pending_residual_sample = {}
        self._pending_spatial_power = {}
        self._pending_coefficients = {}

    def _stability_diagnostics(self) -> Dict[str, float]:
        return {
            "ar/dual_wiener_gain_frozen": float(self.freeze_gains),
            "ar/dual_wiener_gain_delta_alpha_max": self._last_gain_delta_alpha_max,
            "ar/dual_wiener_gain_delta_m_max": self._last_gain_delta_m_max,
            "ar/dual_wiener_gain_update_rejected": self._last_gain_update_rejected,
            "ar/dual_wiener_gain_update_confirmed": self._last_gain_update_confirmed,
            "ar/dual_wiener_gain_updates_rejected_total": float(
                self._gain_updates_rejected
            ),
            "ar/dual_wiener_gain_updates_confirmed_total": float(
                self._gain_updates_confirmed
            ),
            "ar/dual_wiener_noise_guard_ratio": self._last_noise_guard_ratio,
            "ar/dual_wiener_noise_guard_median": self._last_noise_guard_median,
        }

    def diagnostics(self, horizon: int) -> Dict[str, float]:
        horizon = max(1, min(int(horizon), self.max_horizon))
        if self.const_gain is not None:
            value = float(self.const_gain)
            log_reach = float(
                horizon * self.depth * np.log(max(value, 1e-12))
            )
            return {
                "ar/dual_wiener_alpha_mean": value,
                "ar/dual_wiener_alpha_min": value,
                "ar/dual_wiener_alpha_max": value,
                "ar/dual_wiener_m_mean": value,
                "ar/dual_wiener_m_min": value,
                "ar/dual_wiener_m_max": value,
                "ar/dual_wiener_log_identity_reach": log_reach,
                "ar/dual_wiener_noise_fraction": 0.0,
                "ar/dual_wiener_routes_solved": 0.0,
                "ar/dual_wiener_solved_batches": 0.0,
                "ar/dual_wiener_total_probe": 0.0,
                "ar/dual_wiener_noise_probe_abs": 0.0,
                "ar/dual_wiener_external_innovation": 0.0,
                "ar/dual_wiener_min_probes": float(self.min_probes),
                "ar/dual_wiener_probe_ready_fraction": 1.0,
                **self._stability_diagnostics(),
            }
        valid = (
            (self.total_updates[:horizon] >= self.min_probes)
            & (self.noise_updates[:horizon] >= self.min_probes)
        )
        if bool(valid.any()):
            pairs = self.coefficients[:horizon][valid]
            alpha = pairs[:, 0]
            branch = pairs[:, 1]
            total = self.total_moments[:horizon][valid]
            noise = self.noise_moments[:horizon][valid]
            noise_fraction = (
                (noise[:, 0] + noise[:, 2])
                / (total[:, 0] + total[:, 2]).clamp_min(1e-20)
            ).clamp_min(0.0)
            log_reach = torch.log(alpha.clamp_min(1e-12)).sum()
            return {
                "ar/dual_wiener_alpha_mean": float(alpha.mean().detach().cpu()),
                "ar/dual_wiener_alpha_min": float(alpha.min().detach().cpu()),
                "ar/dual_wiener_alpha_max": float(alpha.max().detach().cpu()),
                "ar/dual_wiener_m_mean": float(branch.mean().detach().cpu()),
                "ar/dual_wiener_m_min": float(branch.min().detach().cpu()),
                "ar/dual_wiener_m_max": float(branch.max().detach().cpu()),
                "ar/dual_wiener_log_identity_reach": float(log_reach.detach().cpu()),
                "ar/dual_wiener_noise_fraction": float(noise_fraction.mean().detach().cpu()),
                "ar/dual_wiener_routes_solved": float(valid.sum().detach().cpu()),
                "ar/dual_wiener_solved_batches": float(self.solved_batches.detach().cpu()),
                "ar/dual_wiener_total_probe": self._last_total_probe,
                "ar/dual_wiener_noise_probe_abs": self._last_noise_probe,
                "ar/dual_wiener_external_innovation": float(
                    bool(self.external_innovation_valid[:horizon].any())
                ),
                "ar/dual_wiener_min_probes": float(self.min_probes),
                "ar/dual_wiener_probe_ready_fraction": float(
                    (
                        (self.total_updates[:horizon] >= self.min_probes)
                        & (self.noise_updates[:horizon] >= self.min_probes)
                    ).float().mean().detach().cpu()
                ),
                **self._stability_diagnostics(),
            }
        return {
            "ar/dual_wiener_alpha_mean": 1.0,
            "ar/dual_wiener_alpha_min": 1.0,
            "ar/dual_wiener_alpha_max": 1.0,
            "ar/dual_wiener_m_mean": 1.0,
            "ar/dual_wiener_m_min": 1.0,
            "ar/dual_wiener_m_max": 1.0,
            "ar/dual_wiener_log_identity_reach": 0.0,
            "ar/dual_wiener_noise_fraction": 0.0,
            "ar/dual_wiener_routes_solved": 0.0,
            "ar/dual_wiener_solved_batches": float(self.solved_batches.detach().cpu()),
            "ar/dual_wiener_total_probe": self._last_total_probe,
            "ar/dual_wiener_noise_probe_abs": self._last_noise_probe,
            "ar/dual_wiener_external_innovation": float(
                bool(self.external_innovation_valid[:horizon].any())
            ),
            "ar/dual_wiener_min_probes": float(self.min_probes),
            "ar/dual_wiener_probe_ready_fraction": float(
                (
                    (self.total_updates[:horizon] >= self.min_probes)
                    & (self.noise_updates[:horizon] >= self.min_probes)
                ).float().mean().detach().cpu()
            ),
            **self._stability_diagnostics(),
        }

    @torch.no_grad()
    def export_state(self, horizon: int) -> Dict[str, object]:
        """Return a compact, JSON-safe audit record for a trained gate."""

        horizon = max(1, min(int(horizon), self.max_horizon))
        total = self.total_moments[:horizon].detach().float().cpu()
        noise = self.noise_moments[:horizon].detach().float().cpu()
        valid = (
            (self.total_updates[:horizon] >= self.min_probes)
            & (self.noise_updates[:horizon] >= self.min_probes)
        ).detach().cpu()
        noise_fraction = (
            (noise[..., 0] + noise[..., 2])
            / (total[..., 0] + total[..., 2]).clamp_min(1e-20)
        ).clamp_min(0.0)
        residual_variance = (
            self.residual_second[:horizon]
            - self.residual_mean[:horizon].square()
        ).clamp_min(0.0)
        diagnostics = self.diagnostics(horizon)
        coefficients = self.coefficients[:horizon].detach().float().cpu()
        if self.const_gain is not None:
            coefficients = torch.full_like(coefficients, float(self.const_gain))
            valid = torch.zeros_like(valid, dtype=torch.bool)
        spectral_updates = self.spatial_spectrum_updates[:horizon].detach().cpu()
        spectral_color_rms: List[float] = []
        if self.noise_model == "spatial_spectrum":
            spectral_color_rms = (
                (self.spatial_spectrum_power[:horizon] - 1.0)
                .square()
                .mean(dim=(1, 2, 3))
                .sqrt()
                .detach()
                .float()
                .cpu()
                .tolist()
            )
        return {
            "format_version": 1,
            "estimator": (
                "frozen_constant_gain_baseline"
                if self.const_gain is not None
                else (
                    self._external_process_estimator
                    if self._external_ar_process
                    else (
                        "lagged_crossfitted_innovation_wiener"
                        if bool(self.external_innovation_valid[:horizon].any())
                        else (
                            "lagged_random_phase_spatial_spectrum_wiener"
                            if self.noise_model == "spatial_spectrum"
                            else (
                                "lagged_structured_residual_bootstrap_wiener"
                                if self.noise_model == "lagged_residual_bootstrap"
                                else "lagged_diagonal_gaussian_residual_wiener"
                            )
                        )
                    )
                )
            ),
            "noise_model": self.noise_model,
            "spatial_spectrum_oas": bool(self.spatial_spectrum_oas),
            "const_gain": self.const_gain,
            "external_innovation_file": self.external_innovation_file or None,
            "external_innovation_key": (
                self.external_innovation_key if self.external_innovation_file else None
            ),
            "external_innovation_horizons": int(
                self.external_innovation_valid[:horizon].sum().detach().cpu()
            ),
            "external_innovation_joint_process": bool(self._external_ar_process),
            "external_ar_coefficients": (
                self.external_ar_coefficients.detach().float().cpu().tolist()
                if self._external_ar_process
                and self._external_process_estimator.startswith("oracle_")
                else None
            ),
            "external_ar_transition_matrix": (
                self.external_ar_transition_matrix.detach().float().cpu().tolist()
                if self._external_ar_process
                and self.external_ar_transition_matrix.numel() <= 4096
                else None
            ),
            "external_ar_transition_shape": (
                list(self.external_ar_transition_matrix.shape)
                if self._external_ar_process
                else None
            ),
            "external_ar_observation_shape": (
                list(self.external_ar_observation_matrix.shape)
                if self._external_ar_process
                else None
            ),
            "placement": "internal_per_horizon_per_layer",
            "probe_graph": "fully_open",
            "coefficient_box": [0.0, 1.0],
            "state_dim": self.state_dim,
            "spatial_shape": list(self.spatial_shape) if self.spatial_shape else None,
            "depth": self.depth,
            "horizon": horizon,
            "ema": self.ema,
            "residual_ema": self.residual_ema,
            "warmup_batches": self.warmup_batches,
            "probe_every": self.probe_every,
            "min_probes": self.min_probes,
            "gain_stability": {
                "freeze_gains": bool(self.freeze_gains),
                "delta_open": (
                    None if not np.isfinite(self.gain_delta_open)
                    else float(self.gain_delta_open)
                ),
                "delta_close": (
                    None if not np.isfinite(self.gain_delta_close)
                    else float(self.gain_delta_close)
                ),
                "noise_guard_window": int(self.noise_guard_window),
                "noise_guard_min_history": int(self.noise_guard_min_history),
                "noise_guard_confirmations": int(self.noise_guard_confirmations),
                "noise_guard_bounds": [
                    float(self.noise_guard_lower), float(self.noise_guard_upper)
                ],
                "noise_guard_history": list(self._noise_guard_history),
                "rejected_updates": int(self._gain_updates_rejected),
                "confirmed_shifts": int(self._gain_updates_confirmed),
            },
            "initialization": (
                "arithmetic_mean_then_ema"
                if self.min_probes > 1
                else "first_probe_then_ema"
            ),
            "seen_batches": int(self.seen_batches.detach().cpu()),
            "solved_batches": int(self.solved_batches.detach().cpu()),
            "coefficients_alpha_m": coefficients.tolist(),
            "valid_routes": valid.tolist(),
            "total_moments_ii_ij_jj": total.tolist(),
            "noise_moments_ii_ij_jj": noise.tolist(),
            "noise_trace_fraction": noise_fraction.tolist(),
            "residual_variance_mean_by_horizon": residual_variance.mean(dim=1).float().cpu().tolist(),
            "spatial_spectrum_horizons": int((spectral_updates > 0).sum()),
            "spatial_spectrum_updates_by_horizon": spectral_updates.tolist(),
            "spatial_spectrum_color_rms_by_horizon": spectral_color_rms,
            "spatial_spectrum_oas_shrinkage_by_horizon": (
                self.spatial_spectrum_oas_shrinkage[:horizon]
                .detach().float().cpu().tolist()
                if self.noise_model == "spatial_spectrum"
                else []
            ),
            "summary": diagnostics,
        }
